// =============================================================================
// new-tool — scaffold a new tool that meets the workbench tool contract
// =============================================================================
//
// Every tool in the workbench follows the same on-disk layout:
//
//     tools/<name>/
//       package.json         workspace manifest
//       tool.ts              entry point — calls runTool({...})
//       README.md            GENERATED — do not hand-edit (ADR-0043)
//       goldens/             generated *.golden.json (do not edit by hand)
//
// Neither the README nor the goldens are hand-authored any more. Per
// ADR-0043 (the tool registry is the single source of truth for
// tool-facing docs):
//
//   * `goldens/` is FOLDED from `def.examples` by
//     `scripts/generate-goldens.ts` (issue scientist-workbench-ixnv.3)
//     — the worked input/output pairs you write inside `tool.ts` *are*
//     the goldens. A `tools/<name>/goldens.spec.ts` is now an optional
//     supplement: write one only for inputs you want exercised *beyond*
//     the examples. A tool with no goldens.spec.ts is valid and complete.
//
//   * `README.md` is GENERATED by `scripts/gen-tool-readme.ts` (issue
//     scientist-workbench-ixnv.5): its mechanical sections (Input,
//     Output, Run, Invariants, Standard flags) come from `def`, and its
//     "How it works" prose is extracted from the `tool.ts` literate
//     header (ADR-0043 Decision 5 — the header is canonical). The
//     generated README carries an `AUTOGENERATED` banner and a `check.ts`
//     drift phase enforces it; hand-edits are a build failure. Write the
//     prose in the `tool.ts` literate header, not the README.
//
// This scaffold therefore writes neither a goldens.spec.ts nor a
// hand-authored README. It writes the `tool.ts` skeleton (including a
// `summary` placeholder and an `Intent` literate-header section, both
// required by the generators), then runs `gen-tool-readme.ts` so a
// generated `README.md` exists from the first commit.
//
// `bun scripts/new-tool.ts <name> [--uses pkg1,pkg2,...]` writes the
// skeleton and runs `bun install` so workspace dependencies resolve.
//
// The `--uses` flag was added to retire the prior friction (F3): every tool
// with substantive algorithmic content sits on top of at least one
// workspace package (cas-core, mod-core, future siblings), and editing
// package.json by hand after scaffolding was rote work that interrupted the
// "write the tool" flow. Now the algorithmic substrate is declared up front:
//
//     bun scripts/new-tool.ts cas-reduce  --uses cas-core
//     bun scripts/new-tool.ts ntt         --uses mod-core
//     bun scripts/new-tool.ts geom-orient --uses geom-predicates,float-utils
//
// We validate each name against `packages/<name>/package.json` so a typo
// fails the scaffold immediately rather than producing a half-broken tool
// directory.

import { mkdir, writeFile, access, readFile } from "node:fs/promises";
import { constants as fsConstants } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnBun } from "@workbench/contract";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = dirname(HERE);

// -----------------------------------------------------------------------------
// argv parsing
// -----------------------------------------------------------------------------
//
// Two positional / flag forms:
//   <name> [--uses a,b,c]
//   <name> [--uses=a,b,c]

interface ParsedArgs {
  name: string;
  uses: string[];
}

function parseArgs(argv: string[]): ParsedArgs | { error: string } {
  let name: string | null = null;
  let uses: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]!;
    if (a === "--uses") {
      const next = argv[++i];
      if (next === undefined) return { error: "--uses requires a value" };
      uses = next.split(",").map((s) => s.trim()).filter((s) => s.length > 0);
    } else if (a.startsWith("--uses=")) {
      uses = a.slice("--uses=".length).split(",").map((s) => s.trim()).filter((s) => s.length > 0);
    } else if (a === "--help" || a === "-h") {
      return { error: "help" };
    } else if (a.startsWith("--")) {
      return { error: `unknown flag ${a}` };
    } else {
      if (name !== null) return { error: `unexpected extra positional argument ${a}` };
      name = a;
    }
  }
  if (name === null) return { error: "missing <name> positional argument" };
  return { name, uses };
}

const parsed = parseArgs(process.argv.slice(2));
if ("error" in parsed) {
  if (parsed.error === "help") {
    console.log("usage: bun scripts/new-tool.ts <name> [--uses pkg1,pkg2,...]");
    console.log("");
    console.log("Scaffolds tools/<name>/{package.json, tool.ts, README.md, goldens/}.");
    console.log("README.md is generated by gen-tool-readme.ts; goldens are folded from tool.ts");
    console.log("examples (ADR-0043). Neither a hand-authored README nor a goldens.spec.ts is scaffolded.");
    console.log("--uses adds workspace packages (under packages/<pkg>) as dependencies. Each pkg must already exist.");
    console.log("");
    console.log("examples:");
    console.log("  bun scripts/new-tool.ts cas-reduce  --uses cas-core");
    console.log("  bun scripts/new-tool.ts ntt         --uses mod-core");
    process.exit(0);
  }
  console.error(`new-tool: ${parsed.error}`);
  console.error("usage: bun scripts/new-tool.ts <name> [--uses pkg1,pkg2,...]   (--help for full help)");
  process.exit(2);
}

const { name, uses } = parsed;

if (!/^[a-z][a-z0-9-]*$/.test(name)) {
  console.error(`tool name must match /^[a-z][a-z0-9-]*$/; got ${JSON.stringify(name)}`);
  process.exit(2);
}

// -----------------------------------------------------------------------------
// validate --uses against packages/
// -----------------------------------------------------------------------------
//
// Each package referenced must exist under packages/<pkg>/package.json with
// the canonical `@workbench/<pkg>` name. We read each manifest to confirm
// rather than just checking the directory name — keeps this script honest
// against a future where someone reorganises packages/.

async function exists(p: string): Promise<boolean> {
  try {
    await access(p, fsConstants.F_OK);
    return true;
  } catch {
    return false;
  }
}

const usesResolved: { pkg: string; manifestName: string }[] = [];
for (const pkg of uses) {
  const manifestPath = join(ROOT, "packages", pkg, "package.json");
  if (!(await exists(manifestPath))) {
    console.error(`new-tool: --uses ${pkg}: packages/${pkg}/package.json not found`);
    process.exit(2);
  }
  let manifest: { name?: string };
  try {
    manifest = JSON.parse(await readFile(manifestPath, "utf8")) as { name?: string };
  } catch (e) {
    console.error(`new-tool: --uses ${pkg}: package.json unparseable: ${(e as Error).message}`);
    process.exit(2);
  }
  if (!manifest.name) {
    console.error(`new-tool: --uses ${pkg}: package.json missing 'name' field`);
    process.exit(2);
  }
  usesResolved.push({ pkg, manifestName: manifest.name });
}

const dir = join(ROOT, "tools", name);
if (await exists(dir)) {
  console.error(`refusing to overwrite ${dir} — directory already exists`);
  process.exit(2);
}

// -----------------------------------------------------------------------------
// emit the scaffold
// -----------------------------------------------------------------------------

const dependencyEntries = [
  '    "@workbench/protocol": "workspace:*"',
  '    "@workbench/contract": "workspace:*"',
  ...usesResolved.map((u) => `    ${JSON.stringify(u.manifestName)}: "workspace:*"`),
];

const packageJson = `{
  "name": "@workbench/tool-${name}",
  "version": "0.1.0",
  "type": "module",
  "private": true,
  "dependencies": {
${dependencyEntries.join(",\n")}
  }
}
`;

// The tool.ts template is deliberately *literate*: the comments at the top
// are a chapter introducing the tool's intent, with placeholders that
// invite expansion rather than terse `// TODO` markers. New tools start as
// prose and get refined as code lands.
//
// We import the workspace packages declared via --uses as named imports so
// the IDE picks up the surface area immediately. Unused imports get a
// `void` reference so TS doesn't complain at scaffold time.

const usesImports = usesResolved
  .map((u) => `import * as ${jsIdent(u.pkg)} from "${u.manifestName}";`)
  .join("\n");
const usesVoidRefs = usesResolved.map((u) => `void ${jsIdent(u.pkg)};`).join("\n  ");

function jsIdent(pkg: string): string {
  // packages with hyphens become camelCase identifiers for ergonomic imports.
  return pkg.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
}

const toolTs = `// =============================================================================
// ${name} — <one-line statement of what this tool computes>
// =============================================================================
//
// Intent
// ------
// <Two or three paragraphs of prose. What does this tool do, and why is it
// shaped the way it is? What are the load-bearing invariants? What's
// deliberately out of scope?>
//
// Input shape
// -----------
// <Describe the canonical input. If it's a record, list each field with
// its kind and what role it plays. If it accepts multiple shapes,
// enumerate.>
//
// Output shape
// ------------
// <Describe the canonical output. Note when error-flavoured outputs are
// possible (tagged values, record { ok: false, ... }) — see PRD §6.1 on the
// error-pattern decision.>
//
// Algorithm
// ---------
// <Sketch the algorithm. Cite papers / references. Note any non-obvious
// optimisations.>

import {
  bool,
  int,
  list,
  rat,
  record,
  S,
  str,
  sym,
  tagged,
  ToolError,
  type Value,
} from "@workbench/protocol";
import { defineTool, F, runTool } from "@workbench/contract";
${usesImports}

const NAME = "${name}";
const VERSION = "0.1.0";

// ADR-0010: every tool exports \`def\` (pure data) and gates \`runTool\` on
// \`import.meta.main\` so the registry and tests can import the module
// without spawning a subprocess or consuming stdin.
//
// ADR-0011: declare CLI flags via the \`flags\` field using \`F.bool\` /
// \`F.str\` / \`F.int\` / \`F.enum\`. The runner merges them with the
// standard flag table, parses argv strictly against declared arity,
// and hands \`fn\` a typed \`flags\` object. Tools without flags omit the
// field entirely; \`fn\` then sees \`flags\` as \`{}\`.
export const def = defineTool({
  name: NAME,
  version: VERSION,
  // ADR-0043 Decision 2: \`summary\` is the canonical one-line catalog
  // blurb — one declarative sentence, ≤240 chars, no newline. The
  // generated catalog (\`docs/CATALOG.md\`) uses it as the row text and
  // the generated README (\`tools/${name}/README.md\`) as its opening
  // paragraph. Write a real sentence here before the tool ships.
  summary: "<one declarative sentence — the tool's catalog blurb>",
  schema: {
    // Replace these with concrete S.* schema constructors. \`S.any()\` is
    // the loosest possible declaration — accepts any Value — and is a
    // placeholder, not a destination.
    input: S.any(),
    output: S.any(),
  },
  // Optional. Drop this field entirely if the tool takes no CLI flags.
  // flags: {
  //   verbose: F.bool("emit per-step trace to stderr"),
  //   shots:   F.int("number of samples", { default: 100n, min: 1n }),
  //   mode:    F.enum(["fast", "slow"] as const, "speed knob", { default: "fast" }),
  // },
  examples: [
    // PRD §6.1: aim for one example per code-path branch + edge cases,
    // ≥10 once the tool is "done." For v0.1 prototypes the soft floor is
    // 'every code-path branch covered.'
    {
      description: "<describe>",
      input: int(0n),
      output: int(0n),
    },
  ],
  invariants: [
    {
      name: "deterministic",
      statement: "same input bytes → same output bytes",
      machine_checkable: true,
    },
    // Add domain-specific invariants here. Each should be a one-line
    // statement of a property that holds for *every* in-scope input.
  ],
  fn: (input, _flags): Value => {
    // TODO: implement. The runner has already parsed and validated the
    // input against schema.input before this function runs; tighten
    // schema.input and the \`input\` parameter type narrows automatically.
    // Once you declare \`flags\`, \`_flags\` becomes typed (rename to
    // \`flags\` and access \`flags.<name>\` directly).
    void bool;
    void F;
    void list;
    void rat;
    void record;
    void str;
    void sym;
    void tagged;
    void ToolError;
    ${usesVoidRefs}
    return input;
  },
  // Optional in-process property tests, runnable via \`bun tool.ts --test\`.
  // Use them for invariants checkable against a small set of probes — full
  // workspace tests live in packages/<pkg>/test/.
  // test: () => { ... },
});

if (import.meta.main) void runTool(def);
`;

await mkdir(dir, { recursive: true });
await mkdir(join(dir, "goldens"), { recursive: true });
await writeFile(join(dir, "package.json"), packageJson, "utf8");
await writeFile(join(dir, "tool.ts"), toolTs, "utf8");

console.log(`scaffolded tools/${name}/`);
console.log(`  - package.json`);
if (usesResolved.length > 0) {
  console.log(`      uses: ${usesResolved.map((u) => u.manifestName).join(", ")}`);
}
console.log(`  - tool.ts          (literate template; expand the prose, fill summary/schema/fn/examples/invariants)`);
console.log(`  - goldens/         (folded from tool.ts examples — run \`bun scripts/generate-goldens.ts\`)`);
console.log("");
console.log(`README.md and goldens/ are GENERATED (ADR-0043): the README from`);
console.log(`gen-tool-readme.ts (mechanical sections from \`def\`, prose from the`);
console.log(`tool.ts literate header), the goldens folded from \`def.examples\`.`);
console.log(`Do not hand-edit either — \`bun run check\` enforces both. Write tool`);
console.log(`prose in the tool.ts literate header, not the README.`);
console.log("");

// Auto-resolve workspaces so the next thing the developer types isn't
// `bun install`. We swallow non-zero exit because if `bun install` fails
// it'll print its own diagnostic; we just want to chain the common path.
console.log(`running 'bun install' to resolve workspaces ...`);
const r = await spawnBun(["install"]);
if (r.code !== 0) {
  console.error(`bun install exited ${r.code}; run it manually before iterating`);
  if (r.stderr.trim().length > 0) console.error(r.stderr.trim());
}
console.log("");

// The README is a GENERATED artefact (ADR-0043 Decision 5 / ixnv.5):
// `scripts/gen-tool-readme.ts` derives its mechanical sections from
// `def` and its prose from the `tool.ts` literate header. We invoke the
// generator now — after `bun install` has resolved the new tool's
// workspace deps, so importing the tool module succeeds — leaving a
// valid `README.md` in the tool directory from the first commit. The
// scaffolded `tool.ts` already carries the `Intent` literate-header
// section the generator requires; regenerate after every `def` / header
// edit (`bun run check` enforces it via the per-tool-README drift phase).
console.log(`running 'bun scripts/gen-tool-readme.ts' to generate README.md ...`);
const genReadme = await spawnBun(["scripts/gen-tool-readme.ts"]);
if (genReadme.code !== 0) {
  console.error(`gen-tool-readme exited ${genReadme.code}; run it manually after filling the tool.ts header`);
  if (genReadme.stderr.trim().length > 0) console.error(genReadme.stderr.trim());
} else {
  console.log(`  - README.md        (generated; regenerate with \`bun scripts/gen-tool-readme.ts\`)`);
}
console.log("");
console.log(`next:  bun tools/${name}/tool.ts --version`);
console.log(`       bun tools/${name}/tool.ts --schema`);
console.log(`       (then iterate on tool.ts; run \`bun run check:quick\` between edits)`);
